-- Seed curated Tunceli and Sanliurfa places; idempotent insert.
insert into public.places
(name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,external_id,verified,trust_score,is_active,content_review_status,tags)
select v.name,v.category,v.place_type,v.city,v.address,v.lat,v.lon,v.slug,v.short_desc,v.long_desc,v.source_url,'curated_seed',v.city_key||'-'||v.slug,false,85,true,'source_backed',v.tags::jsonb
from (values
('Munzur Vadisi Milli Parkı','Doğa','Milli park','Tunceli','Tunceli-Ovacık yolu',39.1050::float8,39.5450::float8,'munzur-vadisi-milli-parki','Munzur Suyu boyunca uzanan koruma alanı','Munzur Vadisi, akarsu manzaraları ve dağ ekosistemiyle Tunceli’nin öne çıkan doğal alanıdır.','https://www.kulturportali.gov.tr/turkiye/tunceli/gezilecekyer/munzur-vadisi','tunceli','["doğa","milli park"]'),
('Munzur Gözeleri','Doğa','Kaynak alanı','Ovacık, Tunceli','Ziyaret Köyü, Ovacık',39.3470::float8,39.2070::float8,'munzur-gozeleri','Munzur Suyu’nun kaynak bölgesindeki gözeler','Karstik kaynakların oluşturduğu Munzur Gözeleri, doğal çevresi ve küçük akışlarıyla önemli bir gezi noktasıdır.','https://www.kulturportali.gov.tr/turkiye/tunceli/gezilecekyer/munzur-gozeleri','tunceli','["doğa","kaynak"]'),
('Halbori Gözeleri','Doğa','Kaynak alanı','Tunceli','Munzur Suyu vadisi',39.1250::float8,39.4700::float8,'halbori-gozeleri','Munzur Suyu çevresinde kaynak ve kayalık vadi','Halbori Gözeleri, soğuk kaynak suları ve kayalık vadi manzarasıyla bilinir.','https://fka.gov.tr/tunceli-tanitim','tunceli','["doğa","kaynak"]'),
('Dereova Şelalesi','Doğa','Şelale','Nazımiye, Tunceli','Dereova, Nazımiye',39.1800::float8,39.8250::float8,'dereova-selalesi','Nazımiye yakınlarında doğal şelale','Dereova Şelalesi, çevresindeki dağlık peyzaj ve mevsime göre değişen su debisiyle öne çıkar.','https://fka.gov.tr/tunceli-tanitim','tunceli','["doğa","şelale"]'),
('Pülümür Vadisi','Doğa','Vadi','Pülümür, Tunceli','Tunceli-Pülümür karayolu',39.4900::float8,39.9000::float8,'pulumur-vadisi','Pülümür Çayı boyunca uzanan dağlık vadi','Vadi; akarsu, ormanlık yamaçlar ve kayalık geçitlerden oluşan doğal peyzajıyla tanınır.','https://www.kulturportali.gov.tr/turkiye/tunceli/gezilecekyer/pulumur-vadisi','tunceli','["doğa","vadi"]'),
('Yelmaniye Camii','Tarih ve mimari','Tarihî cami','Çemişgezek, Tunceli','Çemişgezek merkez',38.9160::float8,39.0620::float8,'yelmaniye-camii','Çemişgezek’te taş işçiliğiyle öne çıkan tarihî cami','Yelmaniye Camii, tarihî mimarisi ve taş işçiliğiyle ilçenin önemli kültür mirası yapılarındandır.','https://fka.gov.tr/tunceli-tanitim','tunceli','["tarih","mimari"]'),
('Göbeklitepe Örenyeri','Tarih ve arkeoloji','Örenyeri','Şanlıurfa','Örencik, Haliliye',37.2233::float8,38.9225::float8,'gobeklitepe-orenyeri','Neolitik döneme ait anıtsal arkeolojik alan','Göbeklitepe, tarih öncesi anıtsal yapılarıyla insanlık tarihinin önemli arkeolojik alanlarından biridir.','https://kulturportali.gov.tr/turkiye/sanliurfa/gezilecekyer/gobeklitepe-','sanliurfa','["arkeoloji","neolitik"]'),
('Balıklıgöl','Tarih ve kültür','Tarihî göl kompleksi','Şanlıurfa','Eyyübiye merkez',37.1490::float8,38.7920::float8,'balikligol','Şanlıurfa’nın tarihî merkezindeki göl kompleksi','Balıklıgöl, çevresindeki tarihî ve dinî yapılarla birlikte kentin en bilinen kültür duraklarındandır.','https://www.sanliurfa.bel.tr/kategori/624/0/gezilecek-yerler','sanliurfa','["tarih","kültür"]'),
('Şanlıurfa Arkeoloji Müzesi','Müze','Arkeoloji müzesi','Şanlıurfa','Haliliye merkez',37.1670::float8,38.7900::float8,'sanliurfa-arkeoloji-muzesi','Bölgenin arkeolojik geçmişini tanıtan müze','Müze, Şanlıurfa ve çevresinden tarih öncesi ve tarihî dönemlere ait eserleri bir araya getirir.','https://goturkiye.com/tr/sanliurfa/sanliurfa-rotalari','sanliurfa','["müze","arkeoloji"]'),
('Harran Ulu Camii Kalıntıları','Tarih ve arkeoloji','Cami kalıntısı','Harran, Şanlıurfa','Harran merkez',36.8640::float8,39.0310::float8,'harran-ulu-camii-kalintilari','Harran’da erken İslam dönemi mimari kalıntıları','Harran Ulu Camii kalıntıları, tarihî Harran yerleşiminin önemli arkeolojik mirasları arasındadır.','https://www.kulturportali.gov.tr/turkiye/sanliurfa/gezilecekyer/harran-ulu-camii','sanliurfa','["tarih","arkeoloji"]'),
('Halfeti Tarihî Yerleşimi','Doğa ve kültür','Tarihî yerleşim','Halfeti, Şanlıurfa','Halfeti merkez',37.2470::float8,37.8680::float8,'halfeti-tarihi-yerlesimi','Fırat kıyısında tarihî yerleşim ve su manzarası','Halfeti, Fırat kıyısındaki yerleşim dokusu ve tekne rotalarıyla bilinir; sefer koşulları mevsime göre değişebilir.','https://goturkiye.com/tr/sanliurfa/sanliurfada-yapmadan-donme','sanliurfa','["fırat","tarih"]')
) v(name,category,place_type,city,address,lat,lon,slug,short_desc,long_desc,source_url,city_key,tags)
where not exists (select 1 from public.places p where lower(trim(p.city))=lower(v.city) and (lower(trim(p.name))=lower(v.name) or p.slug=v.slug));